message.content:
{
  "hypotheses": [
    {
      "team": "home",
      "reasons": [
        {
          "text": "홈 경기로 뛰는 쪽이 멕시코라 상대보다 환경 적응 부담이 적다 — 다만 이 대회 유형에는 홈 이점 수치 표가 없어 크기는 알 수 없다(S03).",
          "var_ids": ["S03"]
        },
        {
          "text": "명단 결장 변수(R1)가 존재해 양 팀 미드필드 자원 구성이 평소와 달라지고, 이 변수는 홈 쪽에 유리한 방향으로 잡혀 있다(R1).",
          "var_ids": ["R1"]
        },
        {
          "text": "친선 경기라 교체가 많이 나오므로 벤치 자원과 후반 조정력이 결과를 흔들 수 있고, 그 변수는 양쪽에 열려 있다(S04).",
          "var_ids": ["S04"]
        }
      ],
      "breaks": [
        {
          "text": "8일 안에 이번이 3번째 경기라 체력 부담이 누적되어 후반 집중력이 떨어질 수 있다(IR11-home).",
          "var_ids": ["IR11-home"]
        },
        {
          "text": "최근 4경기 무승으로 마무리 단계에서 골을 만들지 못하는 흐름이 이어지고 있다(IR12-home).",
          "var_ids": ["IR12-home"]
        },
        {
          "text": "최근 5경기 성적이 W L D D L이고 득점 평균 1.2, 보정 0.667로 낮아 득점 생산이 흔들린다(S01-home).",
          "var_ids": ["S01-home"]
        }
      ]
    },
    {
      "team": "away",
      "reasons": [
        {
          "text": "맞대결 10경기 표본에서 3승 3무 4패로 양 팀이 팽팽하게 맞서고 평균 3.0골이 나왔다(S02).",
          "var_ids": ["S02"]
        },
        {
          "text": "상대가 8일 안에 3번째 경기를 치르는 과부하 일정이라 원정팀이 체력에서 상대 우위를 가질 수 있다(IR11-home).",
          "var_ids": ["IR11-home"]
        },
        {
          "text": "직전 경기에서 득점을 기록하며 연속 득점 1경기를 이어가고 있다(S01-away).",
          "var_ids": ["S01-away"]
        }
      ],
      "breaks": [
        {
          "text": "최근 5경기가 L L W L L로 패배가 많고 득점 보정이 0.667로 떨어져 공격 생산이 불안하다(S01-away).",
          "var_ids": ["S01-away"]
        },
        {
          "text": "결장 변수(R1)로 중원 자원에 구멍이 생기면 상대에게 유리하게 흐름이 기울 수 있다(R1).",
          "var_ids": ["R1"]
        },
        {
          "text": "친선 경기 특성상 교체가 많이 이뤄져 원정팀이 리듬을 유지하기 어려울 수 있다(S04).",
          "var_ids": ["S04"]
        }
      ]
    }
  ],
  "scenarios": [
    {
      "id": "대량득점형",
      "outcomes": [[2, 2], [3, 2]],
      "driver_vars": ["S02", "S04"],
      "mechanism": "맞대결 표본의 평균 3.0골 흐름(S02)에 친선 경기의 잦은 교체(S04)가 겹치면 수비 정리가 풀린 채 양 팀이 서로 골을 주고받는 전개가 된다.",
      "type": "대량득점형"
    },
    {
      "id": "우세팀_실점_동반형",
      "outcomes": [[2, 1], [1, 1]],
      "driver_vars": ["S03", "IR12-home", "R1"],
      "mechanism": "홈 경기 환경(S03)과 상대 결장 변수(R1)로 홈팀이 주도권을 쥐지만, 4경기 무승으로 마무리가 아쉬운 흐름(IR12-home) 탓에 한 골을 내주며 쫓기는 형태가 된다.",
      "type": "우세팀_실점_동반형"
    },
    {
      "id": "핸디_대응형",
      "outcomes": [[1, 2], [0, 1]],
      "driver_vars": ["IR11-home", "S01-away", "S02"],
      "mechanism": "상대의 8일 3경기 과부하(IR11-home)로 후반 체력이 빠지고, 원정팀이 직전 경기 득점 흐름(S01-away)과 맞대결에서 나온 골 감각(S02)을 살려 역전 또는 리드를 가져간다.",
      "type": "핸디_대응형"
    },
    {
      "id": "회귀_반전형",
      "outcomes": [[1, 0], [1, 1]],
      "driver_vars": ["S01-home", "S01-away", "IR12-home"],
      "mechanism": "양 팀 모두 최근 5경기 득점 보정이 0.667로 낮고(S01-home, S01-away) 홈팀은 무승 흐름(IR12-home)이라, 최근 기록보다 득점이 줄어든 Tight 한 경기로 수렴한다.",
      "type": "회귀_반전형"
    },
    {
      "id": "친선_실험형",
      "outcomes": [[0, 1], [2, 1]],
      "driver_vars": ["S04", "R1", "S03"],
      "mechanism": "친선 경기의 실험적 라인업과 다수 교체(S04)에 결장 변수(R1)까지 겹쳐 양 팀 전력이 평소와 달라지고, 홈 환경(S03)이 어느 쪽으로든 흐름을 한 번 뒤집는다.",
      "type": "친선_실험형"
    }
  ]
}
